<?php
require_once 'includes/config.php';
require_super_admin();
$message=''; $error='';
function sa_setting(PDO $dbh,string $key,string $fallback=''): string { try{$q=$dbh->prepare('SELECT setting_value FROM srms_system_settings WHERE setting_key=:k');$q->execute([':k'=>$key]);$v=$q->fetchColumn();return $v===false?$fallback:(string)$v;}catch(Throwable $e){return $fallback;} }
if($_SERVER['REQUEST_METHOD']==='POST'){
  $action=(string)($_POST['action']??'');
  try {
    if($action==='create_admin'){
      $username=trim((string)($_POST['username']??''));$password=(string)($_POST['password']??'');$role=(string)($_POST['role']??'admin');
      if(!preg_match('/^[A-Za-z0-9_.@-]{3,100}$/',$username)) throw new RuntimeException('Username must be 3–100 characters and contain only letters, numbers, dot, underscore, @ or hyphen.');
      if(strlen($password)<12) throw new RuntimeException('Password must be at least 12 characters.');
      if(!in_array($role,['admin','super_admin'],true)) throw new RuntimeException('Invalid role.');
      $checkSql='SELECT 1 FROM admin WHERE UserName=:u1 UNION SELECT 1 FROM teachers WHERE username=:u2';
      $checkParams=[':u1'=>$username,':u2'=>$username];
      try {
        $studentColumns=$dbh->query("SELECT COLUMN_NAME FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='tblstudents'")->fetchAll(PDO::FETCH_COLUMN);
        if(in_array('StudentUsername',$studentColumns,true)){
          $checkSql.=' UNION SELECT 1 FROM tblstudents WHERE StudentUsername=:u3';
          $checkParams[':u3']=$username;
        }
      } catch(Throwable $ignored){}
      $checkSql.=' LIMIT 1';
      $q=$dbh->prepare($checkSql);$q->execute($checkParams);if($q->fetchColumn())throw new RuntimeException('That username is already used somewhere in the platform.');
      $q=$dbh->prepare('INSERT INTO admin(UserName,Password,updationDate,Role,IsActive,CreatedAt) VALUES(:u,:p,NOW(),:r,1,NOW())');$q->execute([':u'=>$username,':p'=>password_hash($password,PASSWORD_DEFAULT),':r'=>$role]);
      audit_log($dbh,'SUPERADMIN_CREATE_ADMIN','Created '.$role.' account '.$username);$message='Administrator account created successfully.';
    } elseif($action==='update_admin'){
      $id=(int)($_POST['admin_id']??0);$role=(string)($_POST['role']??'admin');$active=isset($_POST['is_active'])?1:0;
      if($id<1||!in_array($role,['admin','super_admin'],true))throw new RuntimeException('Invalid account update.');
      if($id===(int)$_SESSION['admin_id'] && ($active!==1||$role!=='super_admin'))throw new RuntimeException('You cannot deactivate or demote your own Super Admin account.');
      $q=$dbh->prepare('SELECT id,Role,IsActive,UserName FROM admin WHERE id=:id');$q->execute([':id'=>$id]);$target=$q->fetch();if(!$target)throw new RuntimeException('Administrator account not found.');
      if(($target['Role']==='super_admin' && (int)$target['IsActive']===1) && ($role!=='super_admin'||$active!==1)){$q=$dbh->query("SELECT COUNT(*) FROM admin WHERE Role='super_admin' AND IsActive=1");if((int)$q->fetchColumn()<=1)throw new RuntimeException('At least one active Super Admin must remain.');}
      $q=$dbh->prepare('UPDATE admin SET Role=:r,IsActive=:a,updationDate=NOW() WHERE id=:id');$q->execute([':r'=>$role,':a'=>$active,':id'=>$id]);audit_log($dbh,'SUPERADMIN_UPDATE_ADMIN','Updated account '.$target['UserName'].'; role='.$role.'; active='.$active);$message='Administrator permissions updated.';
    } elseif($action==='reset_password'){
      $id=(int)($_POST['admin_id']??0);$password=(string)($_POST['new_password']??'');if($id<1||strlen($password)<12)throw new RuntimeException('Choose an account and a password of at least 12 characters.');
      $q=$dbh->prepare('SELECT UserName FROM admin WHERE id=:id');$q->execute([':id'=>$id]);$target=$q->fetch();if(!$target)throw new RuntimeException('Administrator account not found.');
      $q=$dbh->prepare('UPDATE admin SET Password=:p,updationDate=NOW() WHERE id=:id');$q->execute([':p'=>password_hash($password,PASSWORD_DEFAULT),':id'=>$id]);audit_log($dbh,'SUPERADMIN_PASSWORD_RESET','Reset password for '.$target['UserName']);$message='Password reset successfully. Share the temporary password securely and ask the user to change it immediately.';
    } elseif($action==='save_settings'){
      $settings=['school_name'=>trim((string)($_POST['school_name']??'')),'school_currency'=>(string)($_POST['school_currency']??'MWK'),'academic_year'=>trim((string)($_POST['academic_year']??''))];
      if($settings['school_name']===''||strlen($settings['school_name'])>180)throw new RuntimeException('School/system name is required and must be 180 characters or fewer.');
      if(!in_array($settings['school_currency'],['MWK','INR','USD','ZAR','GBP'],true))throw new RuntimeException('Unsupported currency.');if(strlen($settings['academic_year'])>30)throw new RuntimeException('Academic year is too long.');
      $q=$dbh->prepare('INSERT INTO srms_system_settings(setting_key,setting_value,updated_by) VALUES(:k,:v,:u) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value),updated_by=VALUES(updated_by)');foreach($settings as $k=>$v)$q->execute([':k'=>$k,':v'=>$v,':u'=>(int)$_SESSION['admin_id']]);audit_log($dbh,'SUPERADMIN_SETTINGS','Updated system-wide settings');$message='System settings saved.';
    } elseif($action==='save_module_permissions'){
      $id=(int)($_POST['admin_id']??0); if($id<1) throw new RuntimeException('Select an administrator.');
      $q=$dbh->prepare("SELECT Role,UserName FROM admin WHERE id=:id");$q->execute([':id'=>$id]);$target=$q->fetch();if(!$target||$target['Role']==='super_admin')throw new RuntimeException('Choose a normal administrator; Super Admin access is unrestricted.');
      $modules=['dashboard','student_class','students','subjects','teachers','results','timetable_exams','student_lifecycle','finance_accounting','notices','management'];
      $dbh->beginTransaction();$del=$dbh->prepare('DELETE FROM srms_admin_permissions WHERE admin_id=:id');$del->execute([':id'=>$id]);
      $ins=$dbh->prepare('INSERT INTO srms_admin_permissions(admin_id,module_key,can_view,can_manage,updated_by) VALUES(:id,:m,:v,:g,:u)');
      foreach($modules as $m){$v=isset($_POST['view'][$m])?1:0;$g=isset($_POST['manage'][$m])?1:0;if($g)$v=1;$ins->execute([':id'=>$id,':m'=>$m,':v'=>$v,':g'=>$g,':u'=>(int)$_SESSION['admin_id']]);}
      $dbh->commit();audit_log($dbh,'SUPERADMIN_PERMISSIONS','Updated module access for '.$target['UserName']);$message='Module permissions saved for '.$target['UserName'].'.';
    } elseif($action==='delete_admin'){
      $id=(int)($_POST['admin_id']??0);if($id<1||$id===(int)$_SESSION['admin_id'])throw new RuntimeException('You cannot delete your own account.');
      $q=$dbh->prepare('SELECT id,Role,IsActive,UserName FROM admin WHERE id=:id');$q->execute([':id'=>$id]);$target=$q->fetch();if(!$target)throw new RuntimeException('Account not found.');
      if($target['Role']==='super_admin'&&(int)$target['IsActive']===1){$q=$dbh->query("SELECT COUNT(*) FROM admin WHERE Role='super_admin' AND IsActive=1");if((int)$q->fetchColumn()<=1)throw new RuntimeException('At least one active Super Admin must remain.');}
      audit_log($dbh,'SUPERADMIN_DELETE_ADMIN','Deleted administrator '.$target['UserName']);$q=$dbh->prepare('DELETE FROM admin WHERE id=:id');$q->execute([':id'=>$id]);$message='Administrator account deleted.';
    } elseif($action==='manage_user_status'){
      $type=(string)($_POST['user_type']??'');$id=(int)($_POST['user_id']??0);$status=(int)($_POST['status']??0);
      if($id<1||!in_array($type,['teacher','student'],true)||!in_array($status,[0,1],true))throw new RuntimeException('Invalid user account change.');
      if($type==='teacher'){$q=$dbh->prepare('UPDATE teachers SET status=:s WHERE id=:id');$q->execute([':s'=>$status,':id'=>$id]);}
      else {$q=$dbh->prepare('UPDATE tblstudents SET Status=:s WHERE StudentId=:id');$q->execute([':s'=>$status,':id'=>$id]);}
      audit_log($dbh,'SUPERADMIN_USER_STATUS',ucfirst($type).' #'.$id.' active='.$status);$message='User account status updated.';
    } elseif($action==='delete_user_account'){
      $type=(string)($_POST['user_type']??'');$id=(int)($_POST['user_id']??0);if($id<1||!in_array($type,['teacher','student'],true))throw new RuntimeException('Invalid account.');
      if($type==='teacher'){$q=$dbh->prepare("UPDATE teachers SET status=0,password=:p WHERE id=:id");$q->execute([':p'=>password_hash(bin2hex(random_bytes(24)),PASSWORD_DEFAULT),':id'=>$id]);}
      else {$q=$dbh->prepare('UPDATE tblstudents SET Status=0,StudentUsername=NULL,StudentPassword=NULL WHERE StudentId=:id');$q->execute([':id'=>$id]);}
      audit_log($dbh,'SUPERADMIN_DELETE_USER_ACCESS','Removed login access for '.$type.' #'.$id.'; academic records preserved');$message='Account access removed. Academic records were retained.';
    } elseif($action==='reset_student_password'){
      $id=(int)($_POST['user_id']??0);$password=(string)($_POST['new_password']??'');if($id<1||strlen($password)<10)throw new RuntimeException('Student password must be at least 10 characters.');
      $q=$dbh->prepare('UPDATE tblstudents SET StudentPassword=:p WHERE StudentId=:id AND StudentUsername IS NOT NULL');$q->execute([':p'=>password_hash($password,PASSWORD_DEFAULT),':id'=>$id]);if(!$q->rowCount())throw new RuntimeException('Student account is missing a username; create/reassign the account first.');audit_log($dbh,'SUPERADMIN_STUDENT_PASSWORD','Reset student password for #'.$id);$message='Student password reset. Share it securely.';
    } else throw new RuntimeException('Unknown action.');
  } catch(Throwable $ex){if($ex instanceof PDOException)error_log('Super Admin action failed: '.$ex->getMessage());$error=$ex instanceof PDOException?'The change could not be saved. Confirm the Phase 13 migration is applied and check server logs.':$ex->getMessage();}
}
$admins=[];try{$admins=$dbh->query('SELECT id,UserName,Role,IsActive,LastLoginAt,CreatedAt FROM admin ORDER BY Role DESC,UserName')->fetchAll();}catch(Throwable $ignored){}
$counts=[];foreach(['admins'=>'SELECT COUNT(*) FROM admin','students'=>'SELECT COUNT(*) FROM tblstudents','teachers'=>'SELECT COUNT(*) FROM tblteachers','classes'=>'SELECT COUNT(*) FROM tblclasses','results'=>'SELECT COUNT(*) FROM tblresult'] as $k=>$sql){try{$counts[$k]=(int)$dbh->query($sql)->fetchColumn();}catch(Throwable $ignored){$counts[$k]=0;}}
$logs=[];try{$logs=$dbh->query('SELECT username,action,details,created_at,ip_address FROM admin_activity_logs ORDER BY id DESC LIMIT 15')->fetchAll();}catch(Throwable $ignored){}
?><!DOCTYPE html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Super Admin | SRMS</title><link rel="stylesheet" href="css/bootstrap.min.css"><link rel="stylesheet" href="css/font-awesome.min.css"><link rel="stylesheet" href="css/main.css"><link rel="stylesheet" href="css/srms-modernization.css"><link rel="stylesheet" href="css/srms-responsive.css"></head><body class="top-navbar-fixed"><div class="main-wrapper"><?php include 'includes/topbar.php';?><div class="content-wrapper"><div class="content-container"><?php include 'includes/leftbar.php';?><div class="main-page"><div class="container-fluid"><div class="row page-title-div"><div class="col-sm-8"><h2 class="title">Super Admin Control Centre</h2><p>Administrator governance, system settings, platform overview and security activity.</p></div></div><?php if($message):?><div class="alert alert-success"><?php echo e($message);?></div><?php endif;?><?php if($error):?><div class="alert alert-danger"><?php echo e($error);?></div><?php endif;?>
<div class="row"><?php foreach(['admins'=>'Administrator accounts','students'=>'Students','teachers'=>'Teachers','classes'=>'Classes','results'=>'Result records'] as $k=>$label):?><div class="col-md-2 col-sm-4 col-xs-6"><div class="panel panel-default"><div class="panel-body"><small><?php echo e($label);?></small><h3><?php echo number_format($counts[$k]??0);?></h3></div></div></div><?php endforeach;?></div>
<div class="row"><div class="col-md-7"><div class="panel panel-primary"><div class="panel-heading"><strong><i class="fa fa-users"></i> Administrator accounts and access</strong></div><div class="panel-body"><div class="table-responsive"><table class="table table-striped"><thead><tr><th>Username</th><th>Role</th><th>Status</th><th>Last login</th><th>Update access</th></tr></thead><tbody><?php foreach($admins as $a):?><tr><td><?php echo e($a['UserName']);?><?php if((int)$a['id']===(int)$_SESSION['admin_id']):?> <span class="label label-info">You</span><?php endif;?></td><td><?php echo e($a['Role']);?></td><td><span class="label label-<?php echo $a['IsActive']?'success':'default';?>"><?php echo $a['IsActive']?'Active':'Disabled';?></span></td><td><?php echo e($a['LastLoginAt']?:'Never');?></td><td><form method="post" class="form-inline"><?php echo csrf_field();?><input type="hidden" name="action" value="update_admin"><input type="hidden" name="admin_id" value="<?php echo (int)$a['id'];?>"><select class="form-control input-sm" name="role"><option value="admin" <?php echo $a['Role']==='admin'?'selected':'';?>>Admin</option><option value="super_admin" <?php echo $a['Role']==='super_admin'?'selected':'';?>>Super Admin</option></select> <label><input type="checkbox" name="is_active" value="1" <?php echo $a['IsActive']?'checked':'';?>> Active</label> <button class="btn btn-xs btn-primary">Save</button></form><form method="post" class="form-inline" style="margin-top:6px"><?php echo csrf_field();?><input type="hidden" name="action" value="reset_password"><input type="hidden" name="admin_id" value="<?php echo (int)$a['id'];?>"><input type="password" name="new_password" class="form-control input-sm" minlength="12" placeholder="New password (12+ chars)" required autocomplete="new-password"><button class="btn btn-xs btn-warning" onclick="return confirm('Reset this administrator password?')">Reset password</button></form><form method="post" style="margin-top:5px" onsubmit="return confirm('Permanently delete this administrator account?')"><?php echo csrf_field();?><input type="hidden" name="action" value="delete_admin"><input type="hidden" name="admin_id" value="<?php echo (int)$a['id'];?>"><button class="btn btn-xs btn-danger" <?php echo (int)$a['id']===(int)$_SESSION['admin_id']?'disabled':'';?>>Delete account</button></form></td></tr><?php endforeach;?><?php if(!$admins):?><tr><td colspan="5">No administrator records were found. Apply the Phase 13 migration.</td></tr><?php endif;?></tbody></table></div></div></div>
<div class="panel panel-default"><div class="panel-heading"><strong><i class="fa fa-user-plus"></i> Create administrator</strong></div><div class="panel-body"><form method="post"><?php echo csrf_field();?><input type="hidden" name="action" value="create_admin"><div class="form-group"><label>Username</label><input class="form-control" name="username" minlength="3" maxlength="100" pattern="[A-Za-z0-9_.@-]+" required></div><div class="form-group"><label>Initial password (minimum 12 characters)</label><input class="form-control" type="password" name="password" minlength="12" required autocomplete="new-password"></div><div class="form-group"><label>Role</label><select class="form-control" name="role"><option value="admin">Admin — routine school administration</option><option value="super_admin">Super Admin — full system governance</option></select></div><button class="btn btn-success">Create account</button></form></div></div></div>
<div class="panel panel-info"><div class="panel-heading"><strong><i class="fa fa-key"></i> Per-administrator module permissions</strong></div><div class="panel-body">
<p>Choose a normal administrator and grant view/manage access. Manage also grants view. Super Admin accounts are unrestricted.</p>
<form method="post"><?php echo csrf_field();?><input type="hidden" name="action" value="save_module_permissions"><div class="form-group"><label>Administrator</label><select name="admin_id" class="form-control" required><option value="">Select administrator</option><?php foreach($admins as $a):if($a['Role']!=='super_admin'):?><option value="<?php echo (int)$a['id'];?>"><?php echo e($a['UserName']);?></option><?php endif;endforeach;?></select></div>
<div class="table-responsive"><table class="table table-bordered"><thead><tr><th>Module</th><th>Can view</th><th>Can manage</th></tr></thead><tbody><?php $moduleLabels=['dashboard'=>'Dashboard','student_class'=>'Student Classes','students'=>'Students','subjects'=>'Subjects','teachers'=>'Teachers','results'=>'Results','timetable_exams'=>'Timetable & Exams','student_lifecycle'=>'Student Lifecycle','finance_accounting'=>'Finance & Accounting','notices'=>'Notices','management'=>'Management'];foreach($moduleLabels as $key=>$label):?><tr><td><?php echo e($label);?></td><td><input type="checkbox" name="view[<?php echo e($key);?>]" value="1"></td><td><input type="checkbox" name="manage[<?php echo e($key);?>]" value="1"></td></tr><?php endforeach;?></tbody></table></div><button class="btn btn-info">Save Module Permissions</button></form></div></div>
<div class="panel panel-warning"><div class="panel-heading"><strong>Teacher/student account suspension</strong></div><div class="panel-body"><div class="row"><div class="col-md-6"><h4>Teachers</h4><div class="table-responsive"><table class="table table-condensed"><tr><th>Username</th><th>Status</th><th>Action</th></tr><?php try{$urows=$dbh->query('SELECT id,username,full_name,status FROM teachers ORDER BY full_name')->fetchAll();foreach($urows as $u):?><tr><td><?php echo e($u['username']);?> <small><?php echo e($u['full_name']);?></small></td><td><?php echo $u['status']?'Active':'Suspended';?></td><td><form method="post"><?php echo csrf_field();?><input type="hidden" name="action" value="manage_user_status"><input type="hidden" name="user_type" value="teacher"><input type="hidden" name="user_id" value="<?php echo (int)$u['id'];?>"><input type="hidden" name="status" value="<?php echo $u['status']?0:1;?>"><button class="btn btn-xs btn-warning"><?php echo $u['status']?'Suspend':'Activate';?></button></form><form method="post" onsubmit="return confirm('Remove this teacher login while preserving linked academic records?')"><?php echo csrf_field();?><input type="hidden" name="action" value="delete_user_account"><input type="hidden" name="user_type" value="teacher"><input type="hidden" name="user_id" value="<?php echo (int)$u['id'];?>"><button class="btn btn-xs btn-danger">Delete access</button></form></td></tr><?php endforeach;}catch(Throwable $ignored){}?></table></div></div><div class="col-md-6"><h4>Students</h4><div class="table-responsive"><table class="table table-condensed"><tr><th>Registration</th><th>Status</th><th>Action</th></tr><?php try{$urows=$dbh->query('SELECT StudentId,StudentName,RollId,Status FROM tblstudents ORDER BY StudentName')->fetchAll();foreach($urows as $u):?><tr><td><?php echo e($u['RollId']?:$u['StudentName']);?></td><td><?php echo $u['Status']?'Active':'Suspended';?></td><td><form method="post"><?php echo csrf_field();?><input type="hidden" name="action" value="manage_user_status"><input type="hidden" name="user_type" value="student"><input type="hidden" name="user_id" value="<?php echo (int)$u['StudentId'];?>"><input type="hidden" name="status" value="<?php echo $u['Status']?0:1;?>"><button class="btn btn-xs btn-warning"><?php echo $u['Status']?'Suspend':'Activate';?></button></form><form method="post" onsubmit="return confirm('Remove this student login while preserving academic records?')"><?php echo csrf_field();?><input type="hidden" name="action" value="delete_user_account"><input type="hidden" name="user_type" value="student"><input type="hidden" name="user_id" value="<?php echo (int)$u['StudentId'];?>"><button class="btn btn-xs btn-danger">Delete access</button></form><form method="post" style="margin-top:4px"><?php echo csrf_field();?><input type="hidden" name="action" value="reset_student_password"><input type="hidden" name="user_id" value="<?php echo (int)$u['StudentId'];?>"><input type="password" name="new_password" class="form-control input-sm" minlength="10" placeholder="New student password" required><button class="btn btn-xs btn-info">Reset password</button></form></td></tr><?php endforeach;}catch(Throwable $ignored){}?></table></div></div></div><p class="text-muted">Suspend/reactivate preserves academic records.</p></div></div>
<div class="col-md-5"><div class="panel panel-info"><div class="panel-heading"><strong><i class="fa fa-cogs"></i> System-wide settings</strong></div><div class="panel-body"><form method="post"><?php echo csrf_field();?><input type="hidden" name="action" value="save_settings"><div class="form-group"><label>School / system name</label><input class="form-control" name="school_name" maxlength="180" required value="<?php echo e(sa_setting($dbh,'school_name','Student Result Management System'));?>"></div><div class="form-group"><label>Default currency</label><select class="form-control" name="school_currency"><?php foreach(['MWK'=>'Malawi Kwacha (MWK)','INR'=>'Indian Rupee (INR)','USD'=>'US Dollar (USD)','ZAR'=>'South African Rand (ZAR)','GBP'=>'British Pound (GBP)'] as $cur=>$label):?><option value="<?php echo e($cur);?>" <?php echo sa_setting($dbh,'school_currency','MWK')===$cur?'selected':'';?>><?php echo e($label);?></option><?php endforeach;?></select></div><div class="form-group"><label>Current academic year</label><input class="form-control" name="academic_year" maxlength="30" placeholder="e.g. 2026/2027" value="<?php echo e(sa_setting($dbh,'academic_year'));?>"></div><button class="btn btn-primary">Save settings</button></form><hr><p class="text-muted"><i class="fa fa-shield"></i> Account changes are logged. Keep at least two trusted Super Admins and use unique strong passwords.</p><p><a href="audit-logs.php" class="btn btn-default btn-sm">View full audit log</a> <a href="change-password.php" class="btn btn-default btn-sm">Change my password</a></p></div></div>
<div class="panel panel-default"><div class="panel-heading"><strong><i class="fa fa-history"></i> Recent administrator activity</strong></div><div class="panel-body"><div class="table-responsive"><table class="table table-condensed"><thead><tr><th>When / Who</th><th>Action</th><th>Details</th></tr></thead><tbody><?php foreach($logs as $log):?><tr><td><small><?php echo e($log['created_at']);?><br><?php echo e($log['username']);?><br><?php echo e($log['ip_address']??'');?></small></td><td><?php echo e($log['action']);?></td><td><?php echo e($log['details']);?></td></tr><?php endforeach;?></tbody></table></div></div></div></div></div></div></div></div></div><script src="js/jquery/jquery-2.2.4.min.js"></script><script src="js/bootstrap/bootstrap.min.js"></script></body></html>
